def total(items):
    """Calcula el total validando price y quantity."""
    if not isinstance(items, list):
        raise TypeError("items debe ser una lista")

    for i, item in enumerate(items):
        if not isinstance(item, dict):
            raise TypeError(f"items[{i}] debe ser un diccionario")

    total = 0.0
    for idx, item in enumerate(items):
        price = float(item.get('price', 0))
        qty = item.get('quantity')

        if qty is None:
            raise ValueError(f"Ítem {idx}: quantity es None (inaceptable)")
        if not isinstance(qty, (int, float)):
            raise TypeError(f"Ítem {idx}: quantity no es numérico '{qty}'")

        total += price * qty

    return round(total, 2)
